struct AiClient {
    http: reqwest::Client,
    groq: ProviderConfig,
    openrouter: ProviderConfig,
    groq_models: Vec<String>,
    openrouter_models: Vec<String>,
}

struct ProviderConfig {
    url: String,
    api_key: String,
    headers: Vec<(&'static str, HeaderValue)>,
}

#[derive(Debug, Clone, Serialize)]
struct ChatTurn {
    role: String,
    content: String,
}

impl ChatTurn {
    fn new(role: &str, content: impl Into<String>) -> Self {
        Self {
            role: role.to_string(),
            content: content.into(),
        }
    }
}

#[derive(Debug, Deserialize)]
struct ChatCompletionResponse {
    #[serde(default)]
    choices: Vec<ChatChoice>,
}

#[derive(Debug, Deserialize)]
struct ChatChoice {
    message: ChatChoiceMessage,
}

#[derive(Debug, Deserialize)]
struct ChatChoiceMessage {
    #[serde(default)]
    content: Option<String>,
}

struct AiReply {
    content: String,
    provider: &'static str,
    model: String,
}

#[derive(Debug)]
struct AiFailure {
    attempts: Vec<String>,
}

impl AiClient {
    fn new(config: &Config) -> Self {
        let http = reqwest::Client::builder()
            .timeout(config.ai_attempt_timeout)
            .connect_timeout(Duration::from_secs(10))
            .pool_idle_timeout(Duration::from_secs(90))
            .pool_max_idle_per_host(4)
            .redirect(reqwest::redirect::Policy::none())
            .user_agent(concat!("school-chat/", env!("CARGO_PKG_VERSION")))
            .build()
            .expect("failed to build the HTTP client");

        Self {
            http,
            groq: ProviderConfig {
                url: config.groq_url.clone(),
                api_key: config.groq_api_key.clone(),
                headers: Vec::new(),
            },
            openrouter: ProviderConfig {
                url: config.openrouter_url.clone(),
                api_key: config.openrouter_api_key.clone(),
                headers: config.openrouter_headers.clone(),
            },
            groq_models: config.groq_models.clone(),
            openrouter_models: config.openrouter_models.clone(),
        }
    }

    /// Try every Groq model in order, then every OpenRouter model in order.
    /// Any provider error (429, 5xx, timeout, malformed response) moves on.
    async fn call_ai(&self, messages: &[ChatTurn]) -> Result<AiReply, AiFailure> {
        let mut attempts: Vec<String> =
            Vec::with_capacity(self.groq_models.len() + self.openrouter_models.len());

        for (index, model) in self.groq_models.iter().enumerate() {
            let started = Instant::now();
            match call_openai_compatible(&self.http, &self.groq, model, messages).await {
                Ok(content) => {
                    info!(
                        provider = "groq",
                        model = %model,
                        attempt = index + 1,
                        latency_ms = started.elapsed().as_millis() as u64,
                        "AI provider succeeded"
                    );
                    return Ok(AiReply {
                        content,
                        provider: "groq",
                        model: model.clone(),
                    });
                }
                Err(err) => {
                    warn!(
                        provider = "groq",
                        model = %model,
                        attempt = index + 1,
                        latency_ms = started.elapsed().as_millis() as u64,
                        error = %err,
                        "AI provider attempt failed"
                    );
                    attempts.push(format!("groq/{model}: {err}"));
                }
            }
        }

        for (index, model) in self.openrouter_models.iter().enumerate() {
            let started = Instant::now();
            match call_openai_compatible(&self.http, &self.openrouter, model, messages).await {
                Ok(content) => {
                    info!(
                        provider = "openrouter",
                        model = %model,
                        attempt = self.groq_models.len() + index + 1,
                        latency_ms = started.elapsed().as_millis() as u64,
                        "AI provider succeeded"
                    );
                    return Ok(AiReply {
                        content,
                        provider: "openrouter",
                        model: model.clone(),
                    });
                }
                Err(err) => {
                    warn!(
                        provider = "openrouter",
                        model = %model,
                        attempt = self.groq_models.len() + index + 1,
                        latency_ms = started.elapsed().as_millis() as u64,
                        error = %err,
                        "AI provider attempt failed"
                    );
                    attempts.push(format!("openrouter/{model}: {err}"));
                }
            }
        }

        error!(attempts = attempts.len(), "all AI provider attempts failed");
        Err(AiFailure { attempts })
    }
}

/// Send one OpenAI-compatible chat completion request and extract the reply.
async fn call_openai_compatible(
    http: &reqwest::Client,
    provider: &ProviderConfig,
    model: &str,
    messages: &[ChatTurn],
) -> Result<String, String> {
    let body = json!({
        "model": model,
        "messages": messages,
        "temperature": 0.6,
        "max_tokens": MAX_REPLY_TOKENS,
    });

    let mut request = http
        .post(&provider.url)
        .bearer_auth(&provider.api_key)
        .json(&body);
    for (name, value) in &provider.headers {
        request = request.header(*name, value.clone());
    }

    let response = request
        .send()
        .await
        .map_err(|err| format!("request failed: {err}"))?;

    let status = response.status();
    let raw_body = response
        .text()
        .await
        .map_err(|err| format!("could not read response body: {err}"))?;

    if !status.is_success() {
        return Err(format!(
            "HTTP {}: {}",
            status.as_u16(),
            truncate_for_log(&raw_body, 300)
        ));
    }

    let parsed: ChatCompletionResponse = serde_json::from_str(&raw_body)
        .map_err(|err| format!("unexpected response shape: {err}"))?;

    let reply = parsed
        .choices
        .into_iter()
        .next()
        .and_then(|choice| choice.message.content)
        .map(|content| content.trim().to_string())
        .filter(|content| !content.is_empty())
        .ok_or_else(|| "provider returned an empty reply".to_string())?;

    Ok(reply)
}

fn truncate_for_log(text: &str, max_chars: usize) -> String {
    if text.chars().count() <= max_chars {
        return text.to_string();
    }
    let mut shortened: String = text.chars().take(max_chars).collect();
    shortened.push('…');
    shortened
}

// ---------------------------------------------------------------------------
// Database
// ---------------------------------------------------------------------------

/// Create the SQLite schema from the SeaORM entity. No hand-written SQL.
async fn init_database(config: &Config) -> Result<DatabaseConnection, DbErr> {
    let in_memory = config.database_url.contains(":memory:");
    let mut options = ConnectOptions::new(config.database_url.clone());
    options
        .max_connections(config.sqlite_max_connections)
        .min_connections(1)
        .connect_timeout(Duration::from_secs(10))
        .acquire_timeout(Duration::from_secs(30))
        .idle_timeout(Duration::from_secs(300))
        .max_lifetime(Duration::from_secs(1_800))
        .sqlx_logging(false)
        .map_sqlx_sqlite_opts(move |sqlite| {
            let sqlite = sqlite
                .create_if_missing(true)
                .foreign_keys(true)
                .busy_timeout(Duration::from_secs(5))
                .synchronous(SqliteSynchronous::Normal);
            if in_memory {
                sqlite.journal_mode(SqliteJournalMode::Memory)
            } else {
                sqlite.journal_mode(SqliteJournalMode::Wal)
            }
        });

    let db = Database::connect(options).await?;
    let backend = db.get_database_backend();
    let schema = Schema::new(backend);

    let create_table = schema
        .create_table_from_entity(ChatMessageEntity)
        .if_not_exists()
        .to_owned();
    db.execute(backend.build(&create_table)).await?;

    info!(
        max_connections = config.sqlite_max_connections,
        journal_mode = if in_memory { "memory" } else { "wal" },
        "database ready (SQLite)"
    );
    Ok(db)
}

async fn load_history(
    db: &DatabaseConnection,
    user_id: &str,
) -> Result<Vec<chat_message::Model>, DbErr> {
    ChatMessageEntity::find()
        .filter(chat_message::Column::UserId.eq(user_id))
        .order_by_asc(chat_message::Column::CreatedAt)
        .order_by_asc(chat_message::Column::Id)
        .all(db)
        .await
}

// ---------------------------------------------------------------------------
// Queue worker
// ---------------------------------------------------------------------------

/// One job at a time, with a fixed cool-down between jobs. This is the whole
/// traffic-control mechanism: providers only ever see a trickle.
async fn worker_loop(
    mut jobs: mpsc::Receiver<ChatJob>,
    mut shutdown: watch::Receiver<bool>,
    db: DatabaseConnection,
    ai: AiClient,
    system_prompt: String,
    spacing: Duration,
) {
    info!("AI worker started (spacing: {:?})", spacing);

    while let Some(job) = jobs.recv().await {
        let ChatJob {
            user_id,
            message,
            respond_to,
        } = job;

        // A client that timed out or navigated away no longer needs an AI
        // call; skip its queued job instead of spending provider quota.
        if respond_to.is_closed() {
            warn!(user_id = %user_id, "dropping queued AI job: client disconnected");
            continue;
        }

        let result = process_chat_job(&db, &ai, &system_prompt, &user_id, &message).await;

        if respond_to.send(result).is_err() {
            warn!(user_id = %user_id, "client disconnected before the reply was ready");
        }

        // During shutdown, skip the cool-down and drain whatever is already
        // queued. New requests have stopped arriving because the HTTP server
        // has finished its graceful shutdown by this point.
        if *shutdown.borrow() {
            continue;
        }

        tokio::select! {
            _ = tokio::time::sleep(spacing) => {}
            changed = shutdown.changed() => {
                if changed.is_ok() {
                    info!("shutdown requested; draining queued AI jobs without spacing");
                }
            }
        }
    }

    info!("AI worker stopped");
}

/// Replay the guest's full history, ask the AI, then persist both turns.
///
/// Messages are written only after a successful AI reply, inside one
/// transaction, so a failed AI call cannot leave an unanswered question in the
/// transcript.
async fn process_chat_job(
    db: &DatabaseConnection,
    ai: &AiClient,
    system_prompt: &str,
    user_id: &str,
    message: &str,
) -> Result<String, JobError> {
    let history = load_history(db, user_id)
        .await
        .map_err(|err| JobError::Internal(format!("failed to load conversation history: {err}")))?;

    let mut turns = Vec::with_capacity(history.len() + 2);
    turns.push(ChatTurn::new("system", system_prompt));
    for saved in &history {
        if saved.role == "user" || saved.role == "assistant" {
            turns.push(ChatTurn::new(&saved.role, saved.content.clone()));
        }
    }
    turns.push(ChatTurn::new("user", message));

    let ai_reply = ai.call_ai(&turns).await.map_err(JobError::AiUnavailable)?;

    let transaction = db
        .begin()
        .await
        .map_err(|err| JobError::Internal(format!("could not start a transaction: {err}")))?;

    let user_created_at: DateTime<Utc> = Utc::now();
    let assistant_created_at: DateTime<Utc> = Utc::now();

    for (role, content, created_at) in [
        ("user", message.to_string(), user_created_at),
        ("assistant", ai_reply.content.clone(), assistant_created_at),
    ] {
        let active = chat_message::ActiveModel {
            user_id: Set(user_id.to_string()),
            role: Set(role.to_string()),
            content: Set(content),
            created_at: Set(created_at),
            ..Default::default()
        };

        active
            .insert(&transaction)
            .await
            .map_err(|err| JobError::Internal(format!("could not save a chat message: {err}")))?;
    }

    transaction
        .commit()
        .await
        .map_err(|err| JobError::Internal(format!("could not commit the transcript: {err}")))?;

    info!(
        user_id = %user_id,
        provider = ai_reply.provider,
        model = %ai_reply.model,
        chars = ai_reply.content.chars().count(),
        "AI reply delivered"
    );
    Ok(ai_reply.content)
}

// ---------------------------------------------------------------------------
// HTTP handlers
// ---------------------------------------------------------------------------

async fn health(State(state): State<AppState>) -> Response {
    if state.jobs.is_closed() {
        error!("health check failed: AI worker queue is closed");
        return api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "The assistant worker is unavailable.",
        );
    }

    match tokio::time::timeout(Duration::from_secs(3), state.db.ping()).await {
        Ok(Ok(())) => (StatusCode::OK, Json(json!({ "status": "ok" }))).into_response(),
        Ok(Err(err)) => {
            error!(error = %err, "health check failed: database ping failed");
            api_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "The database is unavailable.",
            )
        }
        Err(_) => {
            error!("health check failed: database ping timed out");
            api_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "The database did not respond in time.",
            )
        }
    }
}

async fn chat(
    State(state): State<AppState>,
    payload: Result<Json<ChatRequest>, JsonRejection>,
) -> Response {
    let Json(payload) = match payload {
        Ok(payload) => payload,
        Err(rejection) => {
            warn!(error = %rejection.body_text(), "chat payload rejected");
            return api_error(
                StatusCode::BAD_REQUEST,
                "Invalid request. Please refresh the page and try again.",
            );
        }
    };

    // Normalise the browser-generated UUID so casing can never split history.
    let user_id = match Uuid::parse_str(payload.user_id.trim()) {
        Ok(uuid) => uuid.to_string(),
        Err(_) => {
            warn!("chat request rejected: invalid user id");
            return api_error(
                StatusCode::BAD_REQUEST,
                "Invalid user id. Please refresh the page and try again.",
            );
        }
    };

    let message = payload.message.trim();
    if message.is_empty() {
        warn!(user_id = %user_id, "chat request rejected: empty message");
        return api_error(StatusCode::BAD_REQUEST, "Please type a question first.");
    }
    let message_chars = message.chars().count();
    if message_chars > MAX_MESSAGE_CHARS {
        warn!(
            user_id = %user_id,
            message_chars,
            "chat request rejected: message too long"
        );
        return api_error(
            StatusCode::BAD_REQUEST,
            "That message is a little too long. Please shorten it and try again.",
        );
    }

    info!(
        user_id = %user_id,
        message_chars,
        "chat request accepted"
    );

    let (respond_to, response_rx) = oneshot::channel();
    let job = ChatJob {
        user_id: user_id.clone(),
        message: message.to_string(),
        respond_to,
    };

    match state.jobs.try_send(job) {
        Ok(()) => {}
        Err(mpsc::error::TrySendError::Full(_)) => {
            warn!(
                user_id = %user_id,
                capacity = state.queue_capacity,
                "AI queue full; returning 503"
            );
            return status_message(
                StatusCode::SERVICE_UNAVAILABLE,
                "busy",
                "The assistant is busy right now. Please try again in a moment.",
            );
        }
        Err(mpsc::error::TrySendError::Closed(_)) => {
            error!("AI worker queue is closed; returning 503");
            return status_message(
                StatusCode::SERVICE_UNAVAILABLE,
                "error",
                "The assistant is restarting. Please try again in a moment.",
            );
        }
    }

    match tokio::time::timeout(state.chat_response_timeout, response_rx).await {
        Ok(Ok(Ok(reply))) => (
            StatusCode::OK,
            Json(ChatReply {
                status: "ok",
                reply,
            }),
        )
            .into_response(),
        Ok(Ok(Err(JobError::AiUnavailable(failure)))) => {
            error!(
                user_id = %user_id,
                attempts = failure.attempts.len(),
                "chat request failed: all AI providers unavailable"
            );
            api_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "The school assistant is temporarily unavailable. Please try again in a moment.",
            )
        }
        Ok(Ok(Err(JobError::Internal(detail)))) => {
            error!(user_id = %user_id, error = %detail, "chat job failed");
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Something went wrong while preparing the answer. Please try again.",
            )
        }
        Ok(Err(_)) => {
            error!(user_id = %user_id, "chat job response channel closed");
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Something went wrong while preparing the answer. Please try again.",
            )
        }
        Err(_) => {
            warn!(
                user_id = %user_id,
                timeout_secs = state.chat_response_timeout.as_secs(),
                "chat response timed out"
            );
            status_message(
                StatusCode::SERVICE_UNAVAILABLE,
                "busy",
                "The assistant is taking longer than expected. Please try again in a moment.",
            )
        }
    }
}

fn api_error(status: StatusCode, message: &str) -> Response {
    status_message(status, "error", message)
}

fn status_message(status: StatusCode, kind: &'static str, message: impl Into<String>) -> Response {
    (
        status,
        Json(StatusMessage {
            status: kind,
            message: message.into(),
        }),
    )
        .into_response()
}

// ---------------------------------------------------------------------------
// Startup
// ---------------------------------------------------------------------------

struct SchoolKnowledge {
    school_name: String,
    system_prompt: String,
}

fn load_school_knowledge(
    path: &str,
    name_override: Option<&str>,
) -> Result<SchoolKnowledge, String> {
    let contents = std::fs::read_to_string(path).map_err(|err| {
        format!(
            "could not read the school knowledge file '{path}': {err}. \
Set SCHOOL_KNOWLEDGE_PATH to a readable markdown file."
        )
    })?;
    let contents = contents.trim().to_string();
    if contents.is_empty() {
        return Err(format!(
            "the school knowledge file '{path}' is empty. Add the school information before starting."
        ));
    }

    let school_name = name_override
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(ToString::to_string)
        .or_else(|| school_name_from_knowledge(&contents))
        .unwrap_or_else(|| "School".to_string());

    let system_prompt = build_system_prompt(&school_name, &contents);
    Ok(SchoolKnowledge {
        school_name,
        system_prompt,
    })
}

fn school_name_from_knowledge(knowledge: &str) -> Option<String> {
    knowledge.lines().find_map(|line| {
        line.strip_prefix("# ")
            .map(str::trim)
            .filter(|heading| !heading.is_empty())
            .map(ToString::to_string)
    })
}

fn build_system_prompt(school_name: &str, school_knowledge: &str) -> String {
    format!(
        "You are the {school_name} Assistant for parents. \
Read the provided school_knowledge.md carefully to answer the user's question. \
Assume the user is a parent unless they explicitly state they are a student. \
Use only the school information below. If the answer is not present, say that you do not know \
and direct the parent to the main office. Be warm, patient, and professional. \
Keep answers clear and concise. Write plain text only: do not use Markdown syntax such as \
**bold**, headings, or tables.\n\
--- BEGIN school_knowledge.md ---\n\
{school_knowledge}\n\
--- END school_knowledge.md ---"
    )
}

async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(err) = tokio::signal::ctrl_c().await {
            error!(error = %err, "failed to listen for Ctrl+C");
        }
    };

    #[cfg(windows)]
    let ctrl_break = async {
        match tokio::signal::windows::ctrl_break() {
            Ok(mut signal) => {
                signal.recv().await;
            }
            Err(err) => {
                error!(error = %err, "failed to listen for Ctrl+Break");
                std::future::pending::<()>().await;
            }
        }
    };

    #[cfg(not(windows))]
    let ctrl_break = std::future::pending::<()>();

    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut signal) => {
                signal.recv().await;
            }
            Err(err) => {
                error!(error = %err, "failed to listen for SIGTERM");
                std::future::pending::<()>().await;
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => info!("Ctrl+C received"),
        _ = ctrl_break => info!("Ctrl+Break received"),
        _ = terminate => info!("SIGTERM received"),
    }
    info!("shutdown signal received; draining in-flight requests");
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // `.env` is convenient locally; production injects real environment variables.
    dotenvy::dotenv().ok();

    let config = Config::from_env().unwrap_or_else(|error| {
        panic!("startup configuration error:\n{error}");
    });
    init_tracing(config.log_format);

    if !Path::new("static/index.html").is_file() {
        panic!("static/index.html is missing; the frontend cannot be served");
    }

    info!(
        version = env!("CARGO_PKG_VERSION"),
        port = config.port,
        queue_capacity = config.queue_capacity,
        worker_interval_secs = config.worker_interval.as_secs(),
        ai_attempt_timeout_secs = config.ai_attempt_timeout.as_secs(),
        "starting school chat"
    );

    let knowledge =
        load_school_knowledge(&config.school_knowledge_path, config.school_name.as_deref())
            .unwrap_or_else(|error| {
                error!(error = %error, "school knowledge could not be loaded");
                panic!("school knowledge could not be loaded: {error}");
            });

    let db = match init_database(&config).await {
        Ok(db) => db,
        Err(err) => {
            error!(error = %err, "database initialisation failed");
            panic!("database initialisation failed: {err}");
        }
    };

    let ai = AiClient::new(&config);
    let (jobs_tx, jobs_rx) = mpsc::channel::<ChatJob>(config.queue_capacity);
    let (shutdown_tx, shutdown_rx) = watch::channel(false);
    let mut worker = tokio::spawn(worker_loop(
        jobs_rx,
        shutdown_rx,
        db.clone(),
        ai,
        knowledge.system_prompt,
        config.worker_interval,
    ));

    let state = AppState {
        jobs: jobs_tx,
        db: db.clone(),
        queue_capacity: config.queue_capacity,
        chat_response_timeout: config.chat_response_timeout,
    };

    let app = Router::new()
        .route("/chat", post(chat))
        .route("/health", get(health))
        // Serve the single-page UI; unknown paths fall back to index.html.
        .fallback_service(ServeDir::new("static").fallback(ServeFile::new("static/index.html")))
        .layer(DefaultBodyLimit::max(16 * 1024))
        .layer(
            TraceLayer::new_for_http()
                .make_span_with(DefaultMakeSpan::new().level(Level::INFO))
                .on_request(DefaultOnRequest::new().level(Level::INFO))
                .on_response(
                    DefaultOnResponse::new()
                        .level(Level::INFO)
                        .latency_unit(LatencyUnit::Millis),
                )
                .on_failure(DefaultOnFailure::new().level(Level::ERROR)),
        )
        .with_state(state);

    let listener = tokio::net::TcpListener::bind(("0.0.0.0", config.port)).await?;
    info!(
        school = %knowledge.school_name,
        port = config.port,
        queue_capacity = config.queue_capacity,
        worker_interval_secs = config.worker_interval.as_secs(),
        "school chat server listening on http://localhost:{}",
        config.port
    );

    let serve_result = axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await;
    let _ = shutdown_tx.send(true);
    if let Err(err) = &serve_result {
        error!(error = %err, "HTTP server error");
    }

    info!("HTTP server stopped; draining the AI worker");
    match tokio::time::timeout(config.shutdown_timeout, &mut worker).await {
        // The worker logs its own "AI worker stopped" line when it exits.
        Ok(Ok(())) => {}
        Ok(Err(err)) => error!(error = %err, "AI worker task failed"),
        Err(_) => {
            warn!(
                timeout_secs = config.shutdown_timeout.as_secs(),
                "AI worker did not stop in time; aborting"
            );
            worker.abort();
            let _ = worker.await;
        }
    }

    if let Err(err) = db.close_by_ref().await {
        warn!(error = %err, "database pool close failed");
    }
    info!("shutdown complete");
    serve_result?;
    Ok(())
}
